import { useEffect, useRef, useState, useCallback } from "react";
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip
} from "recharts";

// Kraken public WebSocket — browser-friendly, no API key, no geo-restriction
const WS_URL = "wss://ws.kraken.com";

// Kraken pair names → display labels
const PAIRS = ["XBT/USD", "ETH/USD", "SOL/USD"];
const PAIR_LABELS = { "XBT/USD": "BTC/USD", "ETH/USD": "ETH/USD", "SOL/USD": "SOL/USD" };

const ALERT_RULES = {
    "XBT/USD": 70000,
    "ETH/USD": 4000,
    "SOL/USD": 200
};

const ALERT_STORAGE_KEY = "traderAlertThresholds";

const SUBSCRIBE_MSG = JSON.stringify({
    event: "subscribe",
    pair: PAIRS,
    subscription: { name: "trade" }
});

export default function Trader() {
    const [trades, setTrades] = useState({});
    const [alerts, setAlerts] = useState([]);
    const [wsStatus, setWsStatus] = useState("connecting");
    const [alertThresholds, setAlertThresholds] = useState(() => {
        try {
            const saved = JSON.parse(localStorage.getItem(ALERT_STORAGE_KEY) || "null");
            return saved ? { ...ALERT_RULES, ...saved } : ALERT_RULES;
        } catch (_) {
            return ALERT_RULES;
        }
    });

    const socketRef = useRef(null);
    const bufferRef = useRef({});
    const intervalRef = useRef(null);
    const reconnectRef = useRef(null);
    const failCountRef = useRef(0);
    const alertThresholdsRef = useRef(alertThresholds);
    const lastPriceRef = useRef({});

    useEffect(() => {
        alertThresholdsRef.current = alertThresholds;
        localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify(alertThresholds));
    }, [alertThresholds]);

    const connect = useCallback(() => {
        setWsStatus("connecting");
        let ws;
        try {
            ws = new WebSocket(WS_URL);
        } catch (_) {
            setWsStatus("error");
            return;
        }
        socketRef.current = ws;

        ws.onopen = () => {
            failCountRef.current = 0;
            setWsStatus("live");
            ws.send(SUBSCRIBE_MSG);
        };

        ws.onmessage = (event) => {
            try {
                const msg = JSON.parse(event.data);
                // Kraken trade message observed at runtime: [channelId, [[price, volume, time, side, ...]], "trade", "ETH/USD"]
                if (!Array.isArray(msg) || msg[2] !== "trade") return;
                const pair = msg[3];
                const rawTrades = msg[1];
                if (!Array.isArray(rawTrades)) return;

                const now = Date.now();
                rawTrades.forEach(([price, volume]) => {
                    const parsedPrice = parseFloat(price);
                    if (!Number.isFinite(parsedPrice)) return;
                    if (!bufferRef.current[pair]) bufferRef.current[pair] = [];
                    bufferRef.current[pair].push({ price: parsedPrice, time: now });

                    const previousPrice = lastPriceRef.current[pair];
                    const threshold = Number(alertThresholdsRef.current[pair]);
                    const crossedAboveThreshold = Number.isFinite(threshold)
                        && parsedPrice >= threshold
                        && (previousPrice == null || previousPrice < threshold);

                    if (crossedAboveThreshold) {
                        setAlerts(prev => [
                            { pair, price: parsedPrice, time: now, threshold },
                            ...prev.slice(0, 10)
                        ]);
                    }

                    lastPriceRef.current[pair] = parsedPrice;
                });
            } catch (_) {}
        };

        ws.onclose = () => {
            failCountRef.current += 1;
            setWsStatus("connecting");
            reconnectRef.current = setTimeout(() => connect(), Math.min(2000 * failCountRef.current, 10000));
        };

        ws.onerror = () => ws.close();
    }, []);

    useEffect(() => {
        connect();
        return () => {
            if (socketRef.current) {
                socketRef.current.onclose = null;
                socketRef.current.close();
            }
            clearInterval(intervalRef.current);
            clearTimeout(reconnectRef.current);
        };
    }, [connect]);

    // Flush buffer to state every 500ms
    useEffect(() => {
        intervalRef.current = setInterval(() => {
            const buf = bufferRef.current;
            const keys = Object.keys(buf);
            if (keys.length === 0) return;
            setTrades(prev => {
                const updated = { ...prev };
                keys.forEach(pair => {
                    if (buf[pair]?.length > 0) {
                        updated[pair] = [...buf[pair], ...(prev[pair] || [])].slice(0, 50);
                        buf[pair] = [];
                    }
                });
                return updated;
            });
        }, 500);
        return () => clearInterval(intervalRef.current);
    }, []);

    const updateAlertThreshold = useCallback((pair, nextValue) => {
        setAlertThresholds(prev => ({
            ...prev,
            [pair]: nextValue
        }));
    }, []);

    const getSeriesWithMovingAverages = useCallback((pairTrades) => {
        const chronologicalTrades = (pairTrades || []).slice().reverse();

        return chronologicalTrades.map((trade, index, series) => {
            const ma5Window = series.slice(Math.max(0, index - 4), index + 1);
            const ma12Window = series.slice(Math.max(0, index - 11), index + 1);

            const ma5 = ma5Window.reduce((sum, item) => sum + item.price, 0) / ma5Window.length;
            const ma12 = ma12Window.reduce((sum, item) => sum + item.price, 0) / ma12Window.length;

            return {
                time: new Date(trade.time).toLocaleTimeString(),
                price: trade.price,
                ma5,
                ma12
            };
        });
    }, []);

    const statusColor = wsStatus === "live" ? "#00c853" : wsStatus === "error" ? "#d50000" : "#aaa";

    return (
        <div className='containerDetail ml-5 mr-5 bg-lite color-lite mt--25'>
            <div className='containerDetail flexContainer bg-tinted contentLeft'>
                <div className='p-20 size20 contentLeft color-yellow'>
                    📊 Live Trading Dashboard
                </div>
                <span style={{ color: statusColor, fontSize: "0.8em" }}>
                    ● {wsStatus === "live" ? "LIVE" : wsStatus === "error" ? "ERROR" : "CONNECTING…"}
                </span>
            </div>

            {/* 🔔 Alerts Panel */}
            <div className='containerDetail bg-tinted p-10 mt-5 contentLeft'>
                <div className='containerDetail bg-tinted p-10 mt-5 mb-5 color-yellow size20 contentLeft'>
                    🔔 Alerts
                </div>
                <div className='containerDetail bg-tinted height-100 scroll p-10'>
                    {alerts.length === 0 ? (
                        <div>No alerts yet</div>
                    ) : (
                        alerts.map((a, i) => (
                            <div key={i}>
                                {PAIR_LABELS[a.pair] ?? a.pair} → ${a.price.toFixed(2)} @{" "}
                                {new Date(a.time).toLocaleTimeString()} above ${a.threshold.toFixed(2)}
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* 📈 Asset Cards */}
            <div className='containerDetail bg-tinted mt-5 contentLeft'>
                {PAIRS.map(pair => {
                    const data = getSeriesWithMovingAverages(trades[pair]);
                    const latest = trades[pair]?.[0]?.price;
                    const currentThreshold = alertThresholds[pair];
                    const latestPoint = data[data.length - 1];

                    return (
                        <div key={pair} className='containerDetail size20 p-10 m-5 color-yellow bg-tinted contentLeft'>
                            <h3>{PAIR_LABELS[pair]}</h3>
                            <div className='size10 color-orange mt--20 mb-10'>
                                Latest:{" "}
                                {latest != null
                                    ? `$${latest.toFixed(2)}`
                                    : wsStatus === "connecting" ? "Connecting…" : "Waiting for tick…"}
                            </div>
                            <div className='size10 color-lite mb-10'>
                                MA5: {latestPoint ? `$${latestPoint.ma5.toFixed(2)}` : "—"} | MA12: {latestPoint ? `$${latestPoint.ma12.toFixed(2)}` : "—"}
                            </div>
                            <div className='size10 color-lite mb-10'>
                                Alert above:
                                <input
                                    type='number'
                                    step='0.01'
                                    value={currentThreshold}
                                    onChange={(event) => updateAlertThreshold(pair, event.target.value)}
                                    className='containerDetail p-10 ml-5 color-yellow bg-tinted'
                                />
                            </div>
                            <LineChart width={280} height={200} data={data}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="time" hide />
                                <YAxis domain={["auto", "auto"]} />
                                <Tooltip />
                                <Line type="monotone" dataKey="price" dot={false} stroke="#f5b400" strokeWidth={2} />
                                <Line type="monotone" dataKey="ma5" dot={false} stroke="#00c853" strokeWidth={1.5} />
                                <Line type="monotone" dataKey="ma12" dot={false} stroke="#42a5f5" strokeWidth={1.5} />
                            </LineChart>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}